mapper.select:


    AND a.cat_id = #{catId}

    AND a.cat_id IN (SELECT cat_id FROM cat_profile WHERE del_flag = '0' AND base_id = #{catBaseId})
    AND a.cat_id IN (SELECT cat_id FROM cat_profile WHERE del_flag = '0' AND ward_id = #{catWardId})
    AND a.adopter_name like concat('%', #{adopterName}, '%')
    AND a.adopter_phone like concat('%', #{adopterPhone}, '%')
    AND a.adopter_address = #{adopterAddress}
    AND a.adoption_date = #{adoptionDate}
    AND a.agreement_url = #{agreementUrl}
    AND a.visit_closed = #{visitClosed}
    AND a.del_flag = '0'

order by a.adoption_id desc
